(function(root){'use strict';
const key=x=>[x.div,x.workout,x.unit].join('|'),active=r=>['new','paid','refund_requested'].includes(r.status)&&!r.reserve;
function units(data){const seen=new Set();return data.regs.filter(active).map(r=>({...r,unit:r.team?'team:'+r.div+':'+r.team:r.id,members:r.members||[r.personId||r.id]})).filter(r=>{if(seen.has(r.unit))return false;seen.add(r.unit);return true;});}
function required(data){return units(data).flatMap(r=>data.event.workouts.filter(w=>!w.divs.length||w.divs.includes(r.div)).map(w=>({unit:r.unit,div:r.div,workout:w.id,name:r.name,members:r.members,paid:r.status==='paid',fingerprint:JSON.stringify([r.div,r.status==='paid'?'active':r.status,r.members])})));}
const overlaps=(a,b)=>a.start<b.start+b.duration&&b.start<a.start+a.duration;
function generate(data,config,previous=[]){if(!Number.isInteger(config.lanes)||config.lanes<1||!(config.duration>0)||config.gap<0)throw Error('Проверьте дорожки, длительность и переход');
const requiredRows=required(data).filter(x=>config.divs.includes(x.div)&&x.workout===config.workout),heats=structuredClone(previous),assigned=new Set(heats.flatMap(h=>h.slots.map(s=>key({...s,workout:h.workout}))));
const pending=requiredRows.filter(r=>!assigned.has(key(r)));const count=Math.ceil(pending.length/config.lanes);let offset=0;
const occupied=heats.filter(h=>h.venue===config.venue&&h.date===config.date);let start=Math.max(config.start,...occupied.map(h=>h.start+h.duration+config.gap));
for(let i=0;i<count;i++){const size=Math.ceil((pending.length-offset)/(count-i)),rows=pending.slice(offset,offset+size);offset+=size;heats.push({id:'heat-'+cryptoId(),date:config.date,workout:config.workout,divs:[...new Set(rows.map(r=>r.div))],venue:config.venue,lanes:config.lanes,start,duration:config.duration,gap:config.gap,prepare:config.prepare||0,status:'planned',slots:rows.map((r,j)=>({...r,lane:j+1,judge:'',manual:false}))});start+=config.duration+config.gap+(config.prepare||0);}
return heats;}
function cryptoId(){return typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);}
function check(data,heats,windows=[]){const expected=required(data),byKey=new Map(expected.map(r=>[key(r),r])),seen=new Set(),issues=[];const add=(code,message,heat,slot,severity='error')=>issues.push({code,message,heat:heat?.id,unit:slot?.unit,severity});
for(const h of heats){if(h.status==='cancelled')continue;const w=data.event.workouts.find(w=>w.id===h.workout);if(!w)add('workout','Комплекс не найден',h);if(!Number.isFinite(h.start)||!(h.duration>0)||h.start<0||h.start+h.duration>1440)add('time','Некорректное время',h);if(h.duration<(w?.cap||0)/60)add('duration','Заход короче таймкапа',h);if(!h.slots.length)add('empty','Пустой заход',h,null,'warning');const lanes=new Set();for(const s of h.slots){const k=key({...s,workout:h.workout});if(seen.has(k))add('duplicate','Повторное назначение: '+s.name,h,s);seen.add(k);if(!byKey.has(k))add('registration','Заявка отменена или категория не подходит: '+s.name,h,s);else if(s.fingerprint!==byKey.get(k).fingerprint)add('changed','Заявка изменилась: '+s.name,h,s,'warning');if(!h.divs.includes(s.div))add('category','Категория не входит в заход',h,s);if(!Number.isInteger(s.lane)||s.lane<1||s.lane>h.lanes||lanes.has(s.lane))add('lane','Занятая или неверная дорожка',h,s);lanes.add(s.lane);if(data.event.requireJudges&&!s.judge)add('judgeMissing','Не назначен обязательный судья',h,s);if(s.judge&&!data.judges.some(j=>j.id===s.judge&&j.status==='confirmed'))add('judge','Судья не подтверждён',h,s);}
for(const win of windows)if(win.date===h.date&&(!win.venue||win.venue===h.venue)&&overlaps(h,win))add('window','Пересечение с «'+win.name+'»',h);}
const live=heats.filter(h=>h.status!=='cancelled');for(let i=0;i<live.length;i++)for(let j=i;j<live.length;j++){const a=live[i],b=live[j];if(a.date!==b.date)continue;if(i!==j&&a.venue===b.venue){const first=a.start<=b.start?a:b,last=first===a?b:a;if(last.start<first.start+first.duration+first.gap+(last.prepare||0))add('venue','Площадка занята или мало времени для перехода',b);}
if(!overlaps(a,b))continue;for(let x=0;x<a.slots.length;x++)for(let y=0;y<b.slots.length;y++){if(i===j&&y<=x)continue;const s=a.slots[x],t=b.slots[y];if(s.members.some(m=>t.members.includes(m)))add('athleteOverlap','Пересечение спортсмена / состава команды: '+s.name,b,t);if(s.judge&&s.judge===t.judge)add('judgeOverlap','Судья одновременно назначен на две дорожки',b,t);}}
const missing=expected.filter(r=>!seen.has(key(r)));for(const r of missing){const excluded=data.exceptions?.find(e=>e.key===key(r)&&e.reason?.trim());if(!excluded)add('missing','Не распределён: '+r.name,null,r);else add('excluded','Исключение: '+r.name+' — '+excluded.reason,null,r,'warning');}
return {expected:expected.length,assigned:expected.filter(r=>seen.has(key(r))).length,lanes:live.reduce((n,h)=>n+h.slots.length,0),missing,issues,errors:issues.filter(i=>i.severity==='error'),warnings:issues.filter(i=>i.severity==='warning')};}
function recommend(data,heats,row,windows=[]){for(const h of heats){if(h.status!=='planned'||h.workout!==row.workout||!h.divs.includes(row.div))continue;for(let lane=1;lane<=h.lanes;lane++){if(h.slots.some(s=>s.lane===lane))continue;const trial=structuredClone(heats);trial.find(x=>x.id===h.id).slots.push({...row,lane,judge:'',manual:true});const bad=check(data,trial,windows).errors.filter(i=>i.heat===h.id&&i.code!=='judgeMissing');if(!bad.length)return {heat:h.id,lane};}}return null;}
function move(heats,fromId,unit,toId,lane){const copy=structuredClone(heats),a=copy.find(h=>h.id===fromId),b=copy.find(h=>h.id===toId);if(!a||!b||a.workout!==b.workout)throw Error('Перемещение возможно внутри одного комплекса');const index=a.slots.findIndex(s=>s.unit===unit),s=a.slots[index];if(!s||!b.divs.includes(s.div)||lane<1||lane>b.lanes)throw Error('Проверьте категорию и дорожку');const t=b.slots.find(x=>x.lane===lane);a.slots.splice(index,1);if(t){b.slots.splice(b.slots.indexOf(t),1);a.slots.push({...t,lane:s.lane,manual:true});}b.slots.push({...s,lane,manual:true});return copy;}
const api={key,units,required,generate,check,recommend,move};if(typeof module!=='undefined')module.exports=api;else root.Planner=api;
})(globalThis);
